    // (?![^\s])  -> not followed by a non-whitespace char (so: end of text or whitespace)
    // \s?        -> swallows the trailing delimiter, if any, to avoid leaving doubled spaces
    String pattern = "(?<![^\\s])" + Pattern.quote(tag.getText()) + "(?![^\\s])\\s?";
    return text.replaceAll(pattern, "");
}

