    // doubled spaces behind, while line separators are always preserved.
    String pattern = "[ \\t]" + quotedTag + "(?![^\\s])"
            + "|(?<![^\\s])" + quotedTag + "(?![^\\s])[ \\t]?";
    return text.replaceAll(pattern, "");
}

